{
  "scenario": "Обслуживание двух последовательных клиентов",
  "timeline": [
    {"t": 0.0, "event": "Кассир сидит за рабочим местом, дверь кассы закрыта."},
    {"t": 5.0, "event": "Клиент в белой рубашке открывает дверь кассы и входит."},
    {"t": 11.5, "event": "Клиент кладёт на стол документ, кассир начинает проверку."},
    {"t": 25.0, "event": "Кассир передаёт клиенту документ обратно."},
    {"t": 50.0, "event": "Клиент встаёт и выходит из кассы, закрывая за собой дверь."},
    {"t": 55.0, "event": "На столе остаётся пачка купюр (предположительно, предыдущего клиента или остаток), кассир не убирает её в сейф/ящик."},
    {"t": 57.0, "event": "Новый клиент в тёмной одежде подходит к двери кассы."},
    {"t": 60.0, "event": "Новый клиент входит в кассу и садится за стол."},
    {"t": 65.0, "event": "Новый клиент передаёт кассиру документ/деньги на стол."},
    {"t": 70.0, "event": "Кассир работает с документом, пачка купюр всё ещё лежит на столе рядом с новым клиентом."}
  ],
  "violations": [
    {
      "type_id": "foreign_cash_on_desk",
      "timecode_sec": 55.0,
      "confidence": 0.9,
      "obs": "После ухода первого клиента пачка купюр остаётся открыто лежать на рабочем столе. До того как новый клиент начал обслуживание (около 60 с), кассир не убрал деньги в сейф или закрытый ящик, нарушая правило разделения операций разных клиентов."
    }
  ]
